insert into public.admin_help_items(help_key,title_fa,body_fa,warning_fa,title_en,body_en,warning_en,active) values
('checkout.overview','اطلاعات قبل از پرداخت','مشخص کن مشتری برای ساخت سفارش چه اطلاعاتی وارد کند. نوع Checkout می‌تواند فیزیکی، دیجیتال، خدماتی یا ترکیبی باشد.','فقط اطلاعاتی را جمع‌آوری کن که واقعاً برای سفارش لازم است.','Checkout information','Choose what information is required to create an order. Checkout can be physical, digital, service or hybrid.','Collect only information genuinely needed for the order.',true),
('checkout.fields','فیلدهای Checkout','هر فیلد می‌تواند فعال/غیرفعال و اجباری/اختیاری باشد. اعتبارسنجی از قواعد امن از پیش تعریف‌شده انتخاب می‌شود.','برای جلوگیری از اجرای کد، Regex یا Validation دلخواه مدیر در Checkout اجرا نمی‌شود.','Checkout fields','Fields can be enabled/disabled and required/optional. Validation uses predefined safe rules.','Custom executable code or arbitrary validation regex is not allowed in checkout.',true),
('checkout.security','امنیت Checkout','اعتبارسنجی مرورگر فقط برای راحتی کاربر است. سرور باید دوباره نوع، طول و فرمت ورودی را بررسی کند و قیمت، تخفیف، ارسال و موجودی را خودش محاسبه کند.','هیچ مبلغ، وضعیت پرداخت یا قیمت ارسالی از مرورگر قابل اعتماد نیست.','Checkout security','Browser validation is UX only. The server must revalidate type, length and format and independently recalculate price, discounts, shipping and stock.','Never trust browser-supplied totals, payment state or prices.',true)
insert into public.guidance_articles(article_key,area,route_prefix,title_fa,summary_fa,body_fa,title_en,summary_en,body_en,keywords,importance,related_help_keys,active,sort_order) values
('checkout.safe-setup','commerce','/admin/commerce/checkout','راهنمای امن اطلاعات قبل از پرداخت','چه اطلاعاتی بگیریم و چطور امن نگه داریم','برای کالای فیزیکی معمولاً نام، موبایل و اطلاعات ارسال لازم است. برای محصول دیجیتال یا خدمات ممکن است آدرس لازم نباشد. فیلدهای غیرضروری را خاموش کن. اعتبارسنجی سمت مرورگر به‌تنهایی امنیت نیست؛ تمام ورودی‌ها دوباره در سرور بررسی می‌شوند. مبلغ سفارش، تخفیف، موجودی و وضعیت پرداخت نیز فقط در سرور تعیین می‌شوند.','Secure checkout setup','What to collect and how to keep checkout safe','Physical goods usually need name, phone and shipping details; digital goods or services may not need an address. Disable unnecessary fields. Browser validation is not a security boundary: all input is revalidated server-side, and totals, discounts, inventory and payment state are determined only by trusted server logic.',array['checkout','پرداخت','امنیت','آدرس','موبایل','validation','security'],'critical',array['checkout.overview','checkout.fields','checkout.security'],true,22)
